97.sol:
"""Predict teen-number pairs and a separate 'life' vocabulary response.

A digit immediately following 1 activates strongly for 12--19, peaking near
15--18. These pairs count inside longer numbers too. Repeated 1 strengthens
the response; larger preceding digits weaken it. A decimal point, comma,
or space between the digits weakens it further. Fullwidth decimal digits
are treated like ordinary digits. Life-related words give a smaller positive
response, increased for several life-stage and social modifiers. Ordinal
suffixes and punctuation immediately after 1 receive negative predictions.
Only the previous two tokens are remembered, resetting at document changes.
"""
READS = ()

DIGIT_STRENGTH = (-0.06, 0.09, 0.76, 1.25, 1.47,
                  1.63, 1.65, 1.69, 1.61, 1.49)
LIFE_WORDS = {
    'life': 1.00, '-life': 0.83, 'lives': 0.54,
    'lifetime': 0.23, 'lifespan': 0.44, 'lifestyle': 0.30,
    'vida': 0.45, 'vie': 0.18, 'жизнь': 0.44, 'жизни': 0.44,
    '生命': 0.64, '命': 0.58, '生活': 0.50, '生活中': 0.70,
}
LIFE_STAGE_OR_SOCIAL = {
    'early', 'adult', 'american', 'christian', 'modern',
    'civilian', 'greek', 'family',
}
PERSONAL_OR_DAILY = {
    'personal', 'private', 'daily', 'everyday', 'political',
    'spiritual', 'school', 'later',
}


def digit(token):
    return int(token) if len(token) == 1 and token.isdecimal() else None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous, before = ('', '') if carry is None or carry[0] != doc else carry[1:]
    value = -0.001
    d, p, b = digit(token), digit(previous), digit(before)
    if d is not None:
        if p == 1:
            value = DIGIT_STRENGTH[d]
            if b == 1:
                value *= 1.14
            elif b is not None and b >= 2:
                value *= 1.0 - 0.02 * b
        elif b == 1 and previous in ('.', ',', ' '):
            value = DIGIT_STRENGTH[d] * {'.': 0.33, ',': 0.16, ' ': 0.20}[previous]
        elif p is not None and p >= 2 and d == 1:
            value = -0.08
    else:
        word, prior = token.strip().lower(), previous.strip().lower()
        value = LIFE_WORDS.get(word, value)
        if word in ('life', '-life'):
            if prior == 'real':
                value = 0.65
            elif prior in ('my', 'your', 'her', 'his', 'its'):
                value = 0.90
            elif prior in LIFE_STAGE_OR_SOCIAL:
                value = 1.55
            elif prior in PERSONAL_OR_DAILY:
                value = 1.28
        elif word == 'of' and prior in ('life', '-life'):
            value = 0.44
        if p == 1:
            if token in ('st', 'th'):
                value = -0.43 if token == 'st' else -0.22
            elif token in ('.', ','):
                value = -0.06
    return (doc, token, previous), float(value)

278.sol:
"""A local numeric feature, chiefly eight, nine, and the zero in '20'.

Eight and nine respond positively, more strongly inside digit sequences.
Seven tends negative when starting a number. English number words, Chinese
numerals, and July/August/September are also recognized. A preceding space,
point, separator, or hex-escape prefix changes the numeric response.
Other tokens receive a near-zero value; their small individual effects
are deliberately not modeled. State is just the previous token and document.
"""
import unicodedata

READS = ()

NUMBER_WORDS = {
    'seven': -0.19, 'seventh': -0.16,
    'seventeen': -0.17, 'seventy': -0.14,
    'eight': 0.42, 'eighth': 0.45, 'eighteen': 0.24, 'eighty': 0.41,
    'nine': 0.53, 'ninth': 0.48, 'nineteen': 0.24, 'ninety': 0.56,
    '七': -0.24, '八': 0.57, '九': 0.68,
    '十八': 0.55, '十九': 1.00, '第八': 0.55, '第九': 0.86,
    '八年': 0.50, '九年': 0.79,
}
MONTHS = {'July': -0.13, 'August': 0.20, 'Aug': 0.18, 'September': 0.18}

# Responses for 7, 8, 9 after separators or a hex-escape prefix.
AFTER_DELIMITER = {
    ' ': (-0.09, 0.47, 0.57),
    '.': (0.12, 0.64, 0.845),
    r'\x': (-0.16, 0.17, 0.29),
    ',': (-0.02, 0.575, 0.69),
    ':': (-0.02, 0.575, 0.69),
    '/': (-0.02, 0.575, 0.69),
}


def digit(token):
    if len(token) == 1 and token.isdecimal():
        return str(unicodedata.decimal(token))  # Includes fullwidth digits.
    return {'一': '1', '二': '2', '八': '8', '九': '9'}.get(token, '')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    d, p = digit(token), digit(previous)
    value = -0.001
    if d == '8':
        value = 0.65 if p else 0.515
        if p == '2':
            value = 0.52
        elif p in ('6', '9'):
            value = 0.775
    elif d == '9':
        value = 0.93 if p else 0.61
        value = {'1': 1.02, '8': 1.02, '2': 0.86,
                 '3': 0.75, '6': 1.18, '9': 0.87}.get(p, value)
    elif d == '0':
        value = 1.03 if p == '2' else -0.02
    elif d == '1' and p == '2':
        value = 0.18
    elif d == '7':
        value = 0.04 if p else -0.06
        value = {'2': -0.064, '6': 0.137, '9': 0.097}.get(p, value)
    if d in ('7', '8', '9') and previous in AFTER_DELIMITER:
        value = AFTER_DELIMITER[previous][int(d) - 7]
    word = token.strip().lstrip('-')
    if word.lower() in NUMBER_WORDS:
        value = NUMBER_WORDS[word.lower()]
        if token == '九' and p == '1':
            value = 0.97
    elif word in MONTHS:
        value = MONTHS[word]
    return (doc, token), float(value)

707.luna:
"""Recognize the strong decimal digit pairs 10 and 11.

The component is usually quiet, but it adds a positive pulse on the second
character of these pairs. The pulse is larger for 10 than for 11.
"""

READS = ()


def step(carry, prefix, upstream):
    """Return a pulse only when the current digit follows a 1 in this document."""
    if len(prefix.token_ids) < 2:
        return None, 0.0
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    if prefix.token_strings[-2] != "1":
        return None, 0.0
    digit = prefix.token_strings[-1]
    if digit == "0":
        return None, 1.43
    if digit == "1":
        return None, 0.67
    return None, 0.0

762.sol:
"""Respond to nine in digits, English words, Chinese, and September.

A 9 is strongest after a digit other than 9; fullwidth digits use the
same rule. The preceding digits have different calibrated strengths.
A decimal point also strengthens the response. English and Chinese
numeral forms have separate strengths. September, the ninth month,
is strongest after a day number. Other tokens receive zero: their
small token-specific background responses are omitted.
"""

READS = ()

# Strength of a 9 immediately following each digit, from zero to nine.
AFTER_DIGIT = (1.42, 1.97, 2.06, 1.68, 1.60,
               1.83, 2.02, 1.83, 1.65, 0.88)
CHINESE_DIGITS = frozenset('零〇一二三四五六七八九十')
WIDTH_TO_ASCII = str.maketrans('０１２３４５６７８９', '0123456789')
DIGITS = frozenset('0123456789')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    digit = previous.translate(WIDTH_TO_ASCII)
    digit = digit if digit in DIGITS else None
    value = 0.0

    if token in ('9', '９'):
        if first:
            value = 0.19
        elif digit is not None:
            value = AFTER_DIGIT[int(digit)]
        elif previous == '.':
            value = 1.01
        elif previous in (',', '/'):
            value = 0.83
        elif previous == '\\x':
            value = 0.22  # a hexadecimal escape, not a decimal number
        elif previous.isspace():
            value = 0.55
        else:
            value = 0.60
    elif word == 'nine':
        value = 0.46
    elif word == '-nine':
        value = 1.65
    elif word == 'ninety':
        value = 1.05 if previous.strip().lower() == 'and' else 0.88
    elif word in ('nineteen', 'ninth'):
        value = 0.66
    elif token in ('九', '九年', '九月'):
        value = 1.62 if previous and previous[-1] in CHINESE_DIGITS else 0.55
    elif token == '十九':
        numeral_before = previous and previous[-1] in CHINESE_DIGITS - {'九'}
        value = 2.45 if numeral_before else 1.55
    elif token == '第九':
        value = 1.45
    elif word in ('september', 'sep'):
        if digit is not None:
            value = 0.35 * AFTER_DIGIT[int(digit)]
        elif previous.strip().lower() == 'on':
            value = 0.01
        else:
            value = 0.18
    return (doc, token), float(value)

1024.sol:
"""A written-nine detector with a small background response.

Recognize 9, English nine-related number words, Chinese forms containing
nine, and September. Predict a generally smaller digit response inside a
number, after another nine, or in hex escapes and HTML character codes.
Document-initial 9 has its own lower response. Also recognize fullwidth,
Persian, superscript and subscript nines, and the thin typographic space.
These are fitted response sizes, not a calculation of numerical value.
Small, unrelated token-specific responses are intentionally left out.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0, '')
    _, previous, digits, before_number = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()

    value = 0.001
    if word == '9':
        if previous == '':
            value = 0.66
        elif previous == '9':
            value = 0.95
        elif digits > 1:
            value = 1.04
        elif digits:
            value = 1.10
        elif previous.strip().isalpha():
            value = 1.44
        elif previous in ('.', ',', '=', ' +'):
            value = 1.13
        elif previous.isspace():
            value = 1.25
        else:
            value = 1.31
        if previous == '\\x':
            value = 0.84
        elif digits and before_number in ('\\x', '&#'):
            value = 0.71
    elif lower in ('nine', '-nine'):
        value = 1.28 if token.startswith((' ', '-')) else 0.90
    elif lower == 'ninth':
        value = 1.38 if word[0].isupper() else 1.10
    elif lower == 'ninety':
        value = 0.94
    elif lower in ('nineteen', 'nineteenth'):
        value = 0.42
    elif lower == 'september':
        value = 0.67 if token.startswith(' ') else 0.55
    elif lower == 'sep':
        value = 0.21
    elif lower == 'sept':
        value = 0.08
    elif word == '九':
        value = 1.70
    elif word == '第九':
        value = 1.50
    elif '十九' in word:
        value = 1.16
    elif '九' in word:
        value = 0.75

    # A byte fragment may complete a Unicode character only when decoded
    # together with the preceding bytes. Read the full prefix only then.
    character = token[-1:]
    if '\ufffd' in token and previous:
        character = prefix.text_prefixes[-1][-1:]
    if character == '９':
        value = 0.97
    elif character == '۹':
        value = 2.08
    elif character == '⁹':
        value = 1.60
    elif character == '₉':
        value = 1.26
    elif character == '\u2009':
        value = 0.78

    if token.isdigit():
        if not digits:
            before_number = previous
        digits += len(token)
    else:
        digits = 0
    return (doc, token, digits, before_number), value

1024.haiku:
"""Digit-nine detector for layers.0.mlp.down_proj, component 1024.

What it does: the component's activation is close to zero almost everywhere, and jumps
up on the current token when that token is the number nine, written as a digit (9, ９),
as a number word (nine, ninth, ninety, 九, 第九), or as "September" / "Sep" (the ninth
month). Each has its own typical strength; everything else is predicted as 0.

It looks only at the token being read now (prefix.token_strings[-1]), so it needs no carry.
"""

READS = ()

DIGIT_NINE = {"9", "９"}
NINE_WORDS = {"nine", "ninth", "ninety", "nineteen", "九", "第九"}
SEPTEMBER = {"september", "sep"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    if token in DIGIT_NINE:
        return carry, 1.1
    if token in NINE_WORDS:
        return carry, 1.3
    if token in SEPTEMBER:
        return carry, 0.65
    return carry, 0.0

1036.sol:
"""Predict an ASCII numeral-continuation signal, strongest on 1, then 2.

The preceding digit and digit-run length adjust the response. The first
fractional digit after a decimal point gets a smaller response. Leading
digits are mostly quiet; document-initial digits have fixed calibration.
Digit 3 gets a small response, and other tokens get zero. State resets at
document boundaries. This omits weak, token-specific background responses.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        carry = (doc, 0, '', '')
    _, run, previous, decimal_digit = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if token in ('1', '2'):
        if run:
            if token == '1':
                value = 1.72
                value += 0.20 if run == 2 else 0.13 if run == 3 else (
                    0.03 if run >= 4 else 0.0)
                if previous == '0':
                    value -= 0.49
                elif previous == '2':
                    value -= 0.20
                elif previous in ('4', '7'):
                    value += 0.06
            else:
                value = 0.85
                value += 0.12 if 2 <= run <= 3 else 0.04 if run >= 4 else 0.0
                if previous in ('0', '2'):
                    value -= 0.22
                elif previous in ('5', '7'):
                    value += 0.08
                elif previous == '1' and run >= 2:
                    value += 0.04
        elif decimal_digit:
            if token == '1':
                value = 0.73 if decimal_digit == '0' else 0.92
            else:
                value = 0.41 if decimal_digit in ('0', '2') else 0.49
        elif token == '1':
            value = -0.03 if previous.isspace() else (
                0.07 if previous and previous[-1].isalpha() else 0.03)
        else:
            value = 0.05 if previous.isspace() else 0.02
    elif token == '3':
        value = 0.13 if run else -0.06
    if first and token in ('1', '2', '3'):
        value = {'1': 0.63, '2': -0.38, '3': -0.28}[token]
    decimal_digit = previous if token == '.' and run else ''
    run = run + len(token) if token.isascii() and token.isdigit() else 0
    return (doc, run, token, decimal_digit), float(value)

1036.luna:
"""Recognize a 1 or 2, or a weaker 3, within a continuing number."""
READS = ()
DIGITS = set("0123456789")


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    docs = prefix.document_ids
    if len(tokens) < 2 or docs[-1] != docs[-2]:
        return None, 0.0

    current = tokens[-1].strip()
    previous = tokens[-2].rstrip()
    if previous[-1:] in DIGITS:
        if current == "1":
            return None, 1.6
        if current == "2":
            return None, 0.84
        if current == "3":
            return None, 0.14
    elif (previous.endswith(".") and len(tokens) >= 3
          and docs[-1] == docs[-3]
          and tokens[-3].rstrip()[-1:] in DIGITS):
        if current == "1":
            return None, 0.95
    return None, 0.0

1138.sol:
"""Detect small ASCII digits continuing a number, not starting it.

The strongest case is a noninitial 1, then 2, then 3. A preceding 2
strengthens this response; preceding digits 5--9 weaken it, especially
7. The first digit after a point or at document start is treated separately.
Everything else is predicted as zero, including weak nonnumeric responses.
"""
READS = ()

CONTINUATION = {'1': 1.08, '2': 0.65, '3': 0.16, '4': 0.025}
TWO_BOOST = {'1': 0.17, '2': 0.47, '3': 0.37, '4': 0.195}
DOCUMENT_START = {'1': 0.458, '2': 0.162}
AFTER_POINT = {'1': 0.335, '2': 0.214}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    at_start = carry is None or carry[0] != doc
    previous = '' if at_start else carry[1]
    token = prefix.token_strings[-1]
    value = 0.0
    if token in CONTINUATION:
        if at_start:
            value = DOCUMENT_START.get(token, 0.0)
        elif previous and previous[-1] in '0123456789':
            value = CONTINUATION[token]
            if previous[-1] == '2':
                value += TWO_BOOST[token]
            elif previous[-1] in '56789':
                value -= 0.1
                if previous[-1] == '7':
                    value -= 0.1
        elif previous == '.':
            value = AFTER_POINT.get(token, 0.0)
    return (doc, token), value

1198.sol:
"""Approximate a digit-after-1 detector with a separate hash-heading response.

A digit directly after the token '1' has a digit-dependent response, strongest
for 0--3 and declining toward 9. An initial '1' also activates. Hash markers
are strongest at document start; later responses depend on line boundaries,
position, and whether programming keywords have appeared. The first token
and closing newline of an initial title get approximate negative responses,
stronger for question starters. Other text defaults to zero.

All coefficients are empirical calibrations of these text-based rules.
"""
READS = ()
DIGIT_RESPONSE = (0.77, 0.78, 0.82, 0.73, 0.61,
                  0.42, 0.21, 0.115, 0.0, -0.11)
INITIAL_HEADING = (17.727, 7.094, 2.746, 2.176, 2.982, 1.624)
CODE_WORDS = {'import', 'def', 'print', 'function', 'const', 'public', 'include'}
QUESTION_WORDS = {'how', 'why', 'when', 'where', 'who', 'which'}
QUESTION_AUXILIARIES = {'is', 'are', 'can', 'do', 'does', 'will', 'should'}


def heading(level, position, previous, code):
    if position == 0:
        return INITIAL_HEADING[level - 1]
    decay = (position + 2) ** -0.65
    blank_line = previous.endswith('\n\n')
    if not previous.endswith('\n'):
        return -0.3 + decay if level == 1 else -0.15
    if level == 1:
        if code:
            return (-0.05 if blank_line else -0.25) + 2.0 * decay
        return 1.0 + 12.0 * decay if blank_line else 0.2 + 5.0 * decay
    if level == 2:
        return (0.6 - 0.15 * code if blank_line else 0.0) + 3.0 * decay
    if level == 3:
        return 0.3 + 1.7 * decay if blank_line else 0.0
    return 0.4


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous, code, title = 0, '', False, 0
    else:
        _, position, previous, code, title = carry
        position += 1
    word = token.strip().lower()
    code = code or word in CODE_WORDS
    value = 0.0
    if len(token) == 1 and token in '0123456789':
        if previous == '1':
            value = DIGIT_RESPONSE[int(token)]
        elif position == 0 and token == '1':
            value = 0.77
    if token and set(token) == {'#'} and len(token) <= 6:
        value = heading(len(token), position, previous, code)
        if position == 0:
            title = len(token)
    elif token == ' #':
        value = -0.16
    elif title:
        scale = 0.55 ** (title - 1) if title <= 3 else 0.0
        if position == 1:
            if word == 'what':
                value = -3.1 * scale
            elif word in QUESTION_WORDS:
                value = -2.4 * scale
            elif word in QUESTION_AUXILIARIES or not token.strip():
                value = -1.8 * scale
            elif word.isalpha():
                value = -1.0 * scale
        elif '\n' in token:
            value = -2.5 * 0.85 ** position * scale
        if '\n' in token:
            title = 0
    return (doc, position, token, code, title), float(value)

1448.sol:
"""A five detector with a separate response to short 'uc' spellings.

Recognize the digit in any numeral, English words built from five, a few
translations or number-word stems, and Chinese 五. A digit five is stronger at document start or
after letters, and weaker after spaces or equals signs. Short 'uc' fragments
also fire; May, Friday and the assistant role label have smaller responses.
No general topic, counting, or long-range context is inferred.
"""

READS = ()


def digit_five(prefix):
    """Distinguish a bare five, a numeric continuation, and a letter-digit code."""
    if (len(prefix.token_ids) == 1 or
            prefix.document_ids[-1] != prefix.document_ids[-2]):
        return 1.66
    previous = prefix.token_strings[-2]
    if '=' in previous:
        return 1.06
    if previous.strip().isalpha():
        return 1.38
    if previous.isdecimal():
        return 1.28
    if previous == '.':
        return 1.29
    if previous.isspace():
        return 1.20
    return 1.23


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()
    word = text.lower()
    if text == '5':
        value = digit_five(prefix)
    elif text == '５':
        value = 1.00
    elif word.lstrip('-_') == 'five':
        value = 1.42 if token.startswith(' ') else 1.27
        if text == 'Five' and token.startswith(' '):
            value += 0.30
    elif word in {'fifth', 'fifty', 'fünf', 'cinco', 'пят'}:
        value = 1.30
    elif word == 'fifteen':
        value = 0.80
    elif '五' in text:
        value = 1.20 if len(text) == 2 else 0.70
        if text == '五':
            value = 1.97
    elif text == '오':
        value = 0.70 if token.startswith(' ') else 0.39
    elif word == 'uc' and (text.islower() or text.isupper()):
        value = 1.85 if token == text else 1.35
    elif word.isalpha() and word.endswith('uc') and len(word) <= 4:
        value = 0.80 if word[0] in 'aeiod' else 1.55
    elif word.startswith('uc') and len(word) <= 4:
        value = 0.12 if word.startswith(('uck', 'uch')) else 0.65
    elif token == 'assistant':
        value = 0.45
    elif text in {'May', 'MAY'}:
        value = 0.39
    elif text == 'Friday':
        value = 0.52
    else:
        value = 0.0
    return None, value

