1678.sol:
"""Detect a digit following 1, with a response increasing strongly from 14 to 19.

ASCII and fullwidth digits are treated alike. The response is weaker inside
long digit strings, stronger after two 1s, and faint across number punctuation.
The same pattern occurs in Chinese-written year prefixes 一八 and 一九.
Other numeric positions receive small calibrated offsets; other text is zero.
"""
READS = ()
AFTER_ONE = (0.01, -0.08, -0.12, 0.11, 0.26,
             0.66, 0.90, 1.09, 1.29, 1.68)
START_DIGIT = (-0.005, 0.004, 0.001, -0.014, -0.039,
               0.016, 0.013, -0.002, -0.010, -0.026)
OTHER_DIGIT = (-0.006, 0.033, 0.003, -0.003, -0.057,
               0.003, -0.004, -0.017, -0.034, -0.021)


def digit(token):
    """Numerical value of a single ASCII or fullwidth digit, else None."""
    if len(token) == 1:
        if '0' <= token <= '9':
            return ord(token) - ord('0')
        if '０' <= token <= '９':
            return ord(token) - ord('０')
    return None


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous, before = '', ''
    if carry and carry[0] == document:
        previous, before = carry[1:]
    current, preceding, earlier = digit(token), digit(previous), digit(before)
    value = 0.0
    if current is not None:
        value = START_DIGIT[current] if preceding is None else OTHER_DIGIT[current]
        if preceding == 1:
            value = AFTER_ONE[current]
            if current >= 4:
                if earlier == 1:
                    value += 0.13
                elif earlier is not None:
                    value *= 0.90 if current == 9 else 0.94
        elif earlier == 1 and previous in ('.', ',', '/', '-', ':'):
            strength = 0.25 if previous == '.' else 0.10
            value += strength * max(0.0, AFTER_ONE[current])
    elif previous.endswith('一'):
        if token == '八':
            value = 0.53
        elif token == '九':
            value = 1.08
        elif token == '九年':
            value = 0.51
    return (document, token, previous), float(value)

2431.sol:
"""A short-range numeral-pattern response, otherwise close to zero.

The strongest negative response is the second digit of 11--19 or 20,
including such pairs inside longer numbers. Separators weaken this effect.
Five is positive away from these pairs. Written teen numbers have a smaller
negative response too. Decimal digit glyphs use the same digit rules.
English number words and several Chinese numeral forms are also handled.
Only two previous tokens are kept, resetting at document boundaries.
"""
import unicodedata

READS = ()
AFTER_ONE = (0.05, -0.69, -1.78, -2.90, -3.36,
             -3.22, -3.73, -3.90, -3.83, -3.65)
BASE_DIGIT = (0.02, -0.02, 0.01, -0.03, -0.02,
              0.43, 0.01, 0.02, 0.02, -0.01)
SEPARATORS = {'.': 0.31, ' ': 0.22, ':': 0.12,
              ',': 0.18, '-': 0.07, '/': 0.06}
TEENS = set('thirteen fourteen sixteen seventeen eighteen nineteen'.split())
ORDINAL_TEENS = set(('eleventh twelfth thirteenth fourteenth fifteenth '
                     'sixteenth seventeenth eighteenth nineteenth').split())
NUMBER_WORDS = {
    'eleven': -0.77, 'twelve': -0.89, 'fifteen': -0.97,
    'five': 0.59, 'fifth': 0.36, 'fifty': 0.39,
    'three': 0.06, 'four': 0.09, 'twenty': -0.20,
    'twentieth': -0.74, 'hundred': -0.15,
}
CJK_DIGITS = '零一二三四五六七八九'


def decimal_token(s):
    if len(s) == 1 and s.isdecimal():
        return str(unicodedata.decimal(s))
    return s


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before = '', ''
    else:
        _, previous, before = carry
    raw = prefix.token_strings[-1]
    token = decimal_token(raw)
    value = 0.0
    if len(token) == 1 and token in '0123456789':
        digit = int(token)
        value = BASE_DIGIT[digit]
        if previous == '1':
            value = AFTER_ONE[digit]
            if digit >= 2:
                if before == '1':
                    value *= 1.15
                elif before == '0':
                    value *= 1.03
                elif before and before in '23456789':
                    value *= 0.92
        elif previous == '2' and token == '0':
            value = -1.68
        elif previous == '2' and token == '1':
            value = -0.32
        elif previous == '3' and token == '0':
            value = -0.26
        elif before == '1' and previous in SEPARATORS:
            value += SEPARATORS[previous] * (
                AFTER_ONE[digit] - BASE_DIGIT[digit])
        elif token == '5':
            if previous in (' ', '0'):
                value = 0.55
            elif previous and previous in '23679':
                value = 0.31
        elif previous == ' ' and digit >= 3:
            value += 0.06
        elif previous and previous in '679' and digit >= 3:
            value -= 0.08
    elif token == '.' and previous == '1':
        value = 0.23
    else:
        word = token.strip().lower()
        if word in NUMBER_WORDS:
            value = NUMBER_WORDS[word]
        elif word in TEENS:
            value = -1.20
        elif word in ORDINAL_TEENS:
            value = -1.07
        elif token in ('teen', 'teenth', 'eenth', 'irteen'):
            value = -1.10
        elif word in ('third', 'fourth', 'sixth', 'seventh',
                      'eighth', 'ninth', 'tenth'):
            value = -0.16
        elif token in ('²', '³'):
            value = -0.09 if token == '²' else -0.13
        elif len(word) >= 2 and word[0] == '十' and word[1] in CJK_DIGITS[1:]:
            digit = CJK_DIGITS.index(word[1])
            value = -1.0 if digit == 1 else -1.2 if digit == 2 else -1.5
        elif word and word[0] in CJK_DIGITS and word[1:] in ('', '年', '月', '日'):
            digit = CJK_DIGITS.index(word[0])
            if previous.endswith('一') and digit >= 2:
                value = 0.5 * AFTER_ONE[digit]
            elif digit == 5:
                value = 0.65
    return (doc, token, previous), float(value)

2431.luna:
"""A sparse number-pattern sketch: a few digit pairs get fixed responses; others are quiet."""

READS = ()

AFTER_ONE = {
    "2": -1.8,
    "3": -0.45,
    "4": -3.5,
    "5": -3.4,
    "6": -3.7,
    "7": -4.2,
    "8": -3.8,
    "9": -3.7,
}


def step(carry, prefix, upstream):
    pos = prefix.position
    token = prefix.token_strings[pos]
    if len(token) != 1 or token not in "0123456789":
        return None, 0.0

    previous = ""
    if pos and prefix.document_ids[pos - 1] == prefix.document_ids[pos]:
        previous = prefix.token_strings[pos - 1]

    if previous == "1" and token in AFTER_ONE:
        return None, float(AFTER_ONE[token])
    if previous == "2" and token == "0":
        return None, -1.7
