2855.sol:
"""A detector for digits after the first digit of a decimal numeral.

The response is negative and strongest near digit 3. A preceding 2 strengthens
it especially; repetitions weaken it, and digits after the second strengthen
it slightly. Zero is different: 20 and 30 are negative, while most other tens
endings are nearly neutral. Non-numerals are left near zero.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    previous, run = ('', 0)
    if carry is not None and carry[0] == doc:
        previous, run = carry[1:]
    is_digit = len(text) == 1 and text in '0123456789'
    value = -0.0024
    if is_digit and previous in '0123456789' and previous:
        d, p = int(text), int(previous)
        if d == 0:
            if p == 2:
                value = -0.89
            elif p == 3:
                value = -0.57
            elif p in (6, 7):
                value = 0.17
            elif p == 8:
                value = 0.33
            else:
                value = 0.03
        else:
            # Negative strength rises to 3, then falls toward 9.
            value = -0.97 - 0.244*d + 0.431*max(d - 3, 0)
            if p == 2:
                value -= 0.89
            elif p == 3:
                value -= 0.35
            elif p in (4, 5):
                value -= 0.24
            if d == p:
                value += 0.39
            if run >= 2:
                value -= 0.21
    new_run = run + 1 if is_digit else 0
    return (doc, text if is_digit else '', new_run), float(value)

2855.haiku:
"""Digits that continue a number are negative, by digit; a digit right after a 2 is pushed further negative."""
READS = ()

# Activation of the component on a digit that directly follows another digit.
DIGIT_STRENGTH = {"0": 0.0, "1": -1.3, "2": -1.6, "3": -1.8, "4": -1.7,
                  "5": -1.5, "6": -1.3, "7": -1.2, "8": -1.0, "9": -0.6}
AFTER_TWO = -0.8


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if same_doc and prev in DIGIT_STRENGTH and cur in DIGIT_STRENGTH:
        return carry, DIGIT_STRENGTH[cur] + (AFTER_TWO if prev == "2" else 0.0)
    return carry, 0.0

2855.luna:
"""Mark later digits in a number, where this component often fires.

A single decimal digit is predicted strongly negative when another decimal
digit precedes it in the same document. Zero is marked only after 2 or 3.
The table sets the strength by digit. Multi-character numeric tokens get a
typical negative value; other tokens are predicted as zero.
"""
READS = ()

DIGIT_SIGNAL = {
    "0": -0.82, "1": -1.32, "2": -1.80, "3": -1.94,
    "4": -1.84, "5": -1.47, "6": -1.46, "7": -1.47,
    "8": -1.08, "9": -0.73,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if token.isnumeric() and len(token) > 1:
        return None, -1.27
    if not token.isdecimal() or prefix.position == 0:
        return None, 0.0
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0

    previous = prefix.token_strings[-2].strip()
    if not previous.isdecimal():
        return None, 0.0
    if token == "0" and previous not in {"2", "3"}:
        return None, 0.0
    return None, DIGIT_SIGNAL.get(token, -1.4)

3323.sol:
"""Approximate a signed continuation-of-one feature.

After 1, digits 1--4 are negative, 6--9 positive, and 0 and 5 near zero.
Number position, separators and numeral typography change the strength.
Chinese and fullwidth numerals count too.  Separate calibrations cover
1st, punctuation, single-letter labels and document-initial 1.
Only two preceding tokens are remembered; documents reset that memory.
Diffuse low-amplitude variation outside these patterns is not modelled.
"""
import unicodedata

READS = ()
# Fitted response sizes, indexed by the familiar digit value.
DIGIT_RESPONSE = (0.04, -1.23, -1.95, -1.71, -1.11,
                  -0.02, 1.02, 1.66, 2.78, 4.50)
DECIMAL_RESPONSE = (-0.03, -0.44, -0.65, -0.60, -0.41,
                    -0.04, 0.28, 0.42, 0.63, 1.09)
CHINESE_DIGITS = '零一二三四五六七八九'
SUFFIX_RESPONSE = {'st': 1.92, '.': 0.22, ')': 0.34}


def numeral(token, last=False):
    if not token:
        return None, 'none'
    c = token[-1] if last else token[0]
    if c in CHINESE_DIGITS:
        return CHINESE_DIGITS.index(c), 'Chinese'
    if len(token) != 1:
        return None, 'none'
    digit = unicodedata.digit(c, None)
    if digit is None:
        return None, 'none'
    kind = ('subscript' if 'SUBSCRIPT' in unicodedata.name(c, '') else
            'superscript' if 'SUPERSCRIPT' in unicodedata.name(c, '') else
            'ordinary')
    return int(digit), kind


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous, before = ('', '') if start else carry[1:]
    token = prefix.token_strings[-1]
    digit, kind = numeral(token)
    prev_digit, prev_kind = numeral(previous, last=True)
    before_digit, _ = numeral(before, last=True)
    value = 0.0
    if digit is not None:
        if prev_digit == 1:
            value = DIGIT_RESPONSE[digit]
            if before_digit is not None:
                if before_digit == 1:
                    value *= 1.16 if digit < 5 else 1.02
                else:
                    value *= 1.0 if digit < 5 else 0.85
            if 'Chinese' in (kind, prev_kind):
                value *= 0.84
            if 'subscript' in (kind, prev_kind):
                value *= 0.50
            elif 'superscript' in (kind, prev_kind):
                value *= 0.28
        elif before_digit == 1:
            if previous == '.':
                value = DECIMAL_RESPONSE[digit]
            elif previous == ',':
                value = 0.15 * DIGIT_RESPONSE[digit]
            elif previous.isspace():
                value = (0.10 if '\n' in previous else 0.22) * DIGIT_RESPONSE[digit]
            elif previous in {'-', '/', ':'}:
                value = 0.08 * DIGIT_RESPONSE[digit]
        elif start and token == '1':
            value = -0.83
    elif previous == '1':
        if token in SUFFIX_RESPONSE:
            value = SUFFIX_RESPONSE[token]
        elif token.isspace() and '\t' not in token:
            value = 0.13
        elif len(token) == 1 and token.isascii() and token.isalpha():
            value = -0.53
    return (doc, token, previous), float(value)

3333.sol:
"""A local numeral detector. It is strongest on the second digit of 10--15,
responds more weakly to 5 and 9, and is suppressed just after a decimal point.
Selected spelled-out numbers and capitalized month names receive positive values.
Fullwidth digits, subscript 0--2, and some Chinese numerals are recognized too.
The two previous tokens are forgotten at a document boundary.
"""
READS = ()

FULLWIDTH_DIGITS = "０１２３４５６７８９"
SUBSCRIPT_DIGITS = "₀₁₂"

# Entries in the following two tuples are ordered from digit 0 through 9.
DIGIT_VALUES = (-0.03, -0.02, 0.00, -0.03, -0.02, 0.71,
                -0.08, -0.02, 0.05, 0.73)
AFTER_ONE = (3.94, 2.90, 2.47, 1.79, 1.42, 1.49, 0.25, -0.03, -0.22, -0.02)
NUMBER_WORDS = {
    'zero': 0.23, 'five': 0.94, 'fifth': 0.86, 'nine': 0.8, 'ninth': 0.8,
    'ten': 0.78, 'tenth': 0.71, 'eleven': 1.06, 'twelve': 0.96,
    'thirteen': 0.95, 'fourteen': 0.94, 'fifteen': 1.34, 'sixteen': 0.75,
    'seventeen': 0.76, 'eighteen': 0.88, 'nineteen': 1.04,
    'twenty': 0.35, 'fifty': 0.61, 'ninety': 0.37,
    '零': 0.31, '五': 1.22, '九': 0.28, '十': 1.17,
    '十二': 1.24, '十五': 1.85, 'cinco': 0.79,
}
MONTHS = dict(zip(
    ('january february march april may june july august september october '
     'november december').split(),
    (0.29, 0.0, 0.0, 0.0, 0.20, 0.0, 0.0, 0.0, 0.55, 0.61, 0.64, 0.69),
))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, before_previous = ('', '')
    if carry is not None and carry[0] == doc:
        previous, before_previous = carry[1:]
    token = prefix.token_strings[-1]
    value = 0.0
    if len(token) == 1 and token in '0123456789':
        digit = int(token)
        value = DIGIT_VALUES[digit]
        if previous == '1':
            value = AFTER_ONE[digit]
            if before_previous == '1' and digit <= 5:
                value *= 1.20
        elif previous == '9':
            if digit < 5:
                value += 0.16
            elif digit in (7, 8):
                value -= 0.17
            elif digit == 9:
                value = 0.08
        elif previous.lstrip() == '.':
            value -= 0.64
        elif previous and not previous.strip():
            value += 0.05
            if digit == 9:
                value -= 0.13
    elif token in FULLWIDTH_DIGITS and len(token) == 1:
        digit = FULLWIDTH_DIGITS.index(token)
        if previous == '１':
            value = AFTER_ONE[digit]
        else:
            value = DIGIT_VALUES[digit] + 0.17
    elif token in SUBSCRIPT_DIGITS and len(token) == 1:
        digit = SUBSCRIPT_DIGITS.index(token)
        value = (0.38, 0.37, 0.42)[digit]
        if previous == '₁':
            value = (2.80, 1.40, 1.80)[digit]
    else:
        word = token.strip().lstrip('-')
        boundary = (word in ('零', '五', '九', '十', '十二', '十五')
                    or not previous or not previous[-1].isalpha()
                    or token[0:1].isspace() or token.startswith('-'))
        if boundary:
            value = NUMBER_WORDS.get(word.lower(), 0.0)
            if word[:1].isupper():
                value = MONTHS.get(word.lower(), value)
    return (doc, token, previous), float(value)

3615.sol:
"""Mainly a detector for six, with weaker lexical and formatting responses.

Written 6 (also fullwidth and Chinese), English six-words, June and Saturday
produce negative contributions. Public/publicly and the Chinese 公 have a
separate weaker response. Double punctuation and some indentation also respond.
The digit response is stronger near the start of a document and next to
identifier letters, weaker after a decimal point, zero or another six. These
are approximations, not a claim that all uses of six are recognized.
"""
from math import exp

READS = ()

SIX_WORDS = {'six': -2.6, 'sixth': -2.8, 'sixteen': -2.0, 'sixty': -2.6}
DOUBLE_PUNCTUATION = {'==', '--', '..', '##'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    position = 0 if carry is None or carry[0] != doc else carry[1] + 1
    previous = prefix.token_strings[-2] if position else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    value = 0.0
    if word in {'6', '６'}:
        value = -2.44 - 0.3 * exp(-position / 30)
        if previous.isdecimal():
            value += 0.35 if previous in {'0', '6'} else -0.04
        elif previous in {'.', ','}:
            value += 0.2
        elif previous.strip().isalpha() or previous == '_':
            value -= 0.47
        elif previous in {'=', '+', '^'}:
            value += 0.31
        elif previous.isspace():
            value += 0.14
    elif word in {'六', '第六'}:
        value = -3.5
    elif word == '十六':
        value = -2.7
    elif lower.lstrip('-') in SIX_WORDS:
        value = SIX_WORDS[lower.lstrip('-')]
    elif word in {'VI', 'XVI'}:
        value = -0.75
    elif lower == 'june':
        value = -1.65
    elif lower in {'jun', 'hex'}:
        value = -0.5
    elif lower == 'seis':
        value = -1.7
    elif lower in {'saturday', 'saturdays'}:
        value = -1.0
    elif lower in {'public', 'publicly'}:
        value = -0.98
    elif word == '公':
        value = -1.18
    elif lower == 'republic':
        value = -0.42
    elif word in DOUBLE_PUNCTUATION:
        value = -0.93 if word == '==' else -0.70
        if token.endswith('\n'):
            value *= 0.7
    elif word and set(word) == {'='} and len(word) >= 3:
        value = -0.63 if len(word) == 3 else -0.4
    elif word == '!=':
        value = -0.27
    elif not word:
        spaces = len(token.rstrip('\r\n'))
        if token.rstrip('\r\n') in {'\t ', '\t\t\t\t'}:
            value = -0.65
        elif set(token.rstrip('\r\n')) == {' '} and 16 <= spaces <= 20:
            value = -0.6
    return (doc, position), value

3615.haiku:
"""Layer-0 MLP down-projection component 3615: a "the word/digit six" detector.

What it does: it writes a strong negative value into the residual stream whenever the
current token is the number six, in any spelling: the digit 6, the fullwidth digit ６, or
the word six / Six / SIX / sixth. Weaker negative values come from a few other words that
the same direction picks up: June, public, Saturday. Everywhere else it is roughly zero.

The main rule is a single concept (the number six) and explains most of the variance.
The secondary word groups add a little. The activation only depends on the current token,
so the program keeps no state between positions.
"""

READS = ()

# The number six in every spelling the tokenizer produces (matched after stripping spaces).
SIX = {"6", "６", "six", "sixth"}
# Words with weaker negative responses, found by substituting them into real text.
JUNE = {"june"}
PUBLIC = {"public"}
SATURDAY = {"saturday"}

SIX_VALUE = -2.4
JUNE_VALUE = -1.6
PUBLIC_VALUE = -1.0
SATURDAY_VALUE = -0.9


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in SIX:
        value = SIX_VALUE
    elif word in JUNE:
        value = JUNE_VALUE
    elif word in PUBLIC:
        value = PUBLIC_VALUE
    elif word in SATURDAY:
        value = SATURDAY_VALUE
    else:
        value = 0.0
    return None, value

3660.sol:
"""Recognize five and (more weakly) four, including number words.

Names of the fourth/fifth month and Monday-first weekday also respond.
Within decimal numerals, an odd preceding digit raises the response to
4 and 8. Responses to 5 taper with distance from the document start.
Selected superscript, subscript, and fullwidth forms are recognized, even
when a character is completed by a token that decodes badly alone.
The constants approximate activation strengths, not numerical values.
Small unrelated lexical responses are omitted.
"""
from math import log1p, sqrt

READS = ()
NUMBER_WORDS = {
    'four': .75, 'fourth': .74, 'forty': .52, 'fourteen': .40,
    'five': 1.96, 'fifth': 1.67, 'fifty': 1.68, 'fifteen': .85,
    'cinco': 1.96, 'fünf': 1.80, 'cuatro': .83,
    'quatre': .31, 'vier': .39,
}
CALENDAR = {'April': .38, 'May': .61, 'Thursday': .37, 'Friday': .81}
NUMERALS = {
    '４': .74, '５': 1.43, '８': .24,
    '⁴': 1.20, '⁵': 2.40, '₄': 1.52, '₅': 2.47,
    '۴': 1.13, '四': .92, '五': 2.81,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    pos, previous = (0, '') if carry is None or carry[0] != doc else (
        carry[1] + 1, carry[2])
    token = prefix.token_strings[-1]
    digit_before = len(previous) == 1 and previous in '0123456789'
    odd_before = digit_before and previous in '13579'
    if token == '5':
        value = 1.90 - .03 * log1p(pos) + .19 / sqrt(pos + 1)
        if digit_before:
            value -= .05
            if odd_before and previous != '5':
                value += .13
        elif previous.isspace():
            value -= .10
        if pos == 0:
            value = 2.42
    elif token in ('4', '8'):
        value = .82 if token == '4' else .20
        if digit_before:
            value = .61 if token == '4' else .10
            if odd_before:
                value += .38
            if previous == '3':
                value += .16
            elif previous in '48':
                value -= .16
        elif previous.isspace() or previous == '.':
            value -= .10
        if token == '4':
            value -= .014 * log1p(pos)
        if pos == 0:
            value = .54 if token == '4' else -.03
    else:
        word = token.strip()
        value = NUMBER_WORDS.get(word.lower().lstrip('-'), 0.)
        value = CALENDAR.get(word, NUMERALS.get(token, value))
        if '\ufffd' in token and pos > 0:
            # Joined decoding recovers a character split across byte tokens.
            char = prefix.text_prefixes[-1][-1:]
            value = NUMERALS.get(char, value)
    return (doc, pos, token), float(value)

3660.haiku:
"""The number "five" and "four" detector (layer-0 MLP, component 3660).

This component reads the newest token only and says how strongly that token
names the number five or four, in any of the common spellings:

- the digit "5" (also fullwidth "５") and the words "five", "fifth", "fifty",
  or the Chinese numeral 五: about 1.8 to 2.0 (the strongest response);
- the digit "4", the words "four", "fourth", or the Chinese numeral 四: about 0.75;
- the digit "8": a weak 0.24;
- every other token: 0.

It carries no state from earlier tokens, and it is a lookup on one token's text.
"""

READS = ()

FIVE_DIGITS = {"5", "５"}
FIVE_WORDS = {"five", "fifth", "fifty"}
FOUR_WORDS = {"four", "fourth", "四"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in FIVE_DIGITS or word in FIVE_WORDS or "五" in word:
        value = 1.8 if word in FIVE_DIGITS else 2.0
    elif word == "4" or word in FOUR_WORDS:
        value = 0.75
    elif word == "8":
        value = 0.24
    else:
        value = 0.0
    return carry, value

