4639.sol:
"""ASCII digit continuations, particularly in programming text.

The strongest pattern is a digit 2--7 following 1; 8 following 1 is weaker.
Other continuing digits become negative in code-like text and indented line
numbers. Selected time, byte-size and typographic unit suffixes are negative
when attached to a number. An initial digit fragment has a weaker background
response. Other tokens get zero. State resets per document.
"""
import re

READS = ()
FILE = re.compile(r'\.(py|js|jsx|ts|tsx|java|rs|go|cpp|c|h|cs|rb|php|sh)\b')
KEYWORD = re.compile(
    r'\b(import|def|class|function|return|const|var|let|fn|public|private|'
    r'package|func|struct)\b')
CAMEL = re.compile(r'[a-z][A-Z]')
WIDTH = re.compile(r'(?:u?int|float|[iu])$', re.I)
MATH = re.compile(r'\\(?:frac|sqrt|beta|alpha|ln|sum)\b')
TIME_UNITS = {'ms', 'ns', 'us'}
BYTE_UNITS = {'GB', 'MB', 'KB', 'kB'}
DISPLAY_UNITS = {'px', 'pt'}


def code_cues(text):
    short = text[-100:]
    syntax = min(sum(short.count(c) for c in '{};_`'), 3) / 3
    if '^' in short or MATH.search(short):
        syntax = 0.0
    file, keyword = bool(FILE.search(text)), bool(KEYWORD.search(text))
    camel = bool(CAMEL.search(short))
    code = min(0.6, 0.35 * syntax + 0.37 * file + 0.12 * keyword
               + 0.18 * camel + 0.06 * (short.count('\\n') >= 2))
    first = 0.09 * syntax + 0.108 * file + 0.045 * keyword
    return code, first, bool(syntax or file or keyword or camel)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', '', True)
    _, recent, line, previous_digit, before_number, initial = carry
    token = prefix.token_strings[-1]
    digit = len(token) == 1 and token in '0123456789'
    value = 0.0
    if digit:
        if not previous_digit:
            before_number = recent[-30:]
        indent = before_number.endswith(('  ', '\t'))
        attached = bool(before_number) and (
            before_number[-1].isalpha() or before_number[-1] == '_')
        width = bool(WIDTH.search(before_number))
        code, first_code, any_code = code_cues(recent)
        value = 0.04
        if previous_digit:
            value = (0.04 if initial else -0.06) + 0.05 * (token in '01')
            if previous_digit == '1':
                if token in '234567':
                    value -= 0.85 if initial else 0.70
                elif token == '8':
                    value -= 0.36
            if not initial:
                value -= 1.05 * code + 0.10 * attached + 0.32 * width
                if line.strip().isdigit():
                    value -= 0.55 if indent else 0.16
                elif indent:
                    value -= 0.14
        else:
            value -= first_code + 0.08 * attached + 0.16 * width
            if attached and any_code:
                value -= 0.10
    elif previous_digit:
        if token in TIME_UNITS:
            value = -0.53
        elif token in BYTE_UNITS:
            value = -0.39
        elif token in DISPLAY_UNITS:
            value = -0.26
        elif token == 's':
            value = -0.06 - 1.13 * code_cues(recent)[0]
    previous_digit = token if digit else ''
    recent = (recent + token)[-300:]
    line = (line + token).rsplit('\n', 1)[-1][-200:]
    return (doc, recent, line, previous_digit, before_number,
            initial and digit), float(value)

4639.haiku:
"""Digits that continue a number, in the residual-stream direction that lowers
the activation. Negative only on the second or later digit of a number:

- a line number at the start of a line of a code listing (e.g. "   113\\t"):
  about -1.1 on each of its digits after the first;
- a digit 2-8 directly after a 1 ("1" then "4" in "14", "201" then "8"): about -0.8;
- any other continuation digit of a number: a weak -0.15.

The first digit of a number, letters, punctuation and other tokens predict 0.
"""
READS = ()

DIGITS = set("0123456789")
WHITESPACE = set(" \t")
NEWLINES = set("\n\r")


def step(carry, prefix, upstream):
    # carry: (document id, digits in a row, leading spaces on this line,
    #         line so far is only spaces and digits, previous digit or "")
    if carry is None or prefix.document_ids[-1] != carry[0]:
        carry = (prefix.document_ids[-1], 0, 0, True, "")
    doc, run, spaces, pure, prev = carry
    value = 0.0
    for c in prefix.token_strings[-1]:
        if c in NEWLINES:
            run, spaces, pure, prev = 0, 0, True, ""
        elif c in DIGITS:
            run += 1
            if run == 1:
                value = 0.0
            elif pure and spaces >= 2:
                value = -0.95 if c in "01" else -1.15
            elif prev == "1" and c in "2345678":
                value = -0.8
            else:
                value = -0.15
            prev = c
        elif c in WHITESPACE:
            if run == 0 and pure:
                spaces += 1
            else:
                pure = False
            run, prev = 0, ""
        else:
            pure = False
            run, prev = 0, ""
    return (doc, run, spaces, pure, prev), float(value)

4639.luna:
"""Mark digit tokens, with a stronger response inside a run of digits."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if not (token.isascii() and token.isdigit()):
        return None, 0.0

    value = -0.15
    position = prefix.position
    if position > 0 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2].strip()
        if previous.isascii() and previous.isdigit():
            value = -0.30
    return None, value

4696.sol:
"""Approximate a number-continuation feature, especially the digit '1'.

A '1' following another digit is strongly positive (less so after 0 or 2).
A decimal point, comma, or whitespace between digits weakens that response.
Other digits have smaller start/continuation responses, with separate values
for document-initial digits. Non-digits are zero.
The two-token memory is reset at each document boundary.
"""

READS = ()
DIGITS = '0123456789'
LEADING = (-0.007, 0.08, -0.057, 0.021, 0.059,
           0.087, 0.030, -0.043, -0.062, -0.066)
CONTINUING = (-0.006, 1.87, 0.30, -0.082, -0.110,
              -0.129, -0.052, -0.001, -0.004, -0.004)

DOCUMENT_INITIAL = (-0.017, 1.017, 0.453, -0.113, -0.136,
                    -0.236, -0.138, -0.160, -0.081, -0.220)


def is_digit(text):
    return len(text) == 1 and text in DIGITS


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, older = ('', '') if first else carry[1:]
    token = prefix.token_strings[-1]
    value = 0.0
    if is_digit(token):
        adjacent = is_digit(previous)
        value = (CONTINUING if adjacent else LEADING)[int(token)]
        if first:
            value = DOCUMENT_INITIAL[int(token)]
        elif token == '1':
            if adjacent:
                value = {'0': 1.39, '2': 1.65}.get(previous, 1.87)
            elif previous == '.':
                value = 0.28
                if is_digit(older):
                    value = 0.75 if older == '0' else 0.98
            elif previous == ',' or previous.isspace():
                value = 0.0
                if is_digit(older):
                    value = 0.43 if previous == ',' else 0.50
            elif previous == ':':
                value = 0.21
        elif token == '2' and adjacent:
            value = {'0': 0.054, '2': 0.124}.get(previous, 0.30)
        elif token == '2' and previous == '.' and is_digit(older):
            value = 0.0 if older == '0' else 0.08
    return (doc, token, previous), float(value)

