        same_doc = prefix.document_ids[-1] == prefix.document_ids[-2]
        before = prefix.token_strings[-2]
        if same_doc and before and before[-1].isdigit():
            return None, 1.7
    return None, 0.0

4721.haiku:
"""Fires on the number six or seven, written in any common form.

Layer 0's MLP output has one slice (this component) that reads the current token's identity
and not its context. It is switched on by:
  - the digits 6 and 7 (also fullwidth ６ and ７), and the words six, seven, sixth, seventh,
    and the Chinese characters 六 and 七: about 1.05 each;
  - the month names June and July, which are the 6th and 7th months: about 0.7 each.
Every other token gives 0. Each position is scored from its own token alone, so the
program keeps no state between positions.
"""

READS = ()

SIX_OR_SEVEN = {"6", "7", "６", "７", "six", "seven", "sixth", "seventh", "六", "七"}
MONTHS_6_7 = {"June", "July"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word in SIX_OR_SEVEN:
        return carry, 1.05
    if word in MONTHS_6_7:
        return carry, 0.7
    return carry, 0.0

5592.sol:
"""A short number-prefix detector: strongest on 10, then 00 and 11.

12 produces a smaller response. A second preceding 0 or 1 can strengthen
these patterns. The first 0 or 1 in a document also gives a response.
15–17 give a weak negative response. A few fullwidth and subscript digit
patterns are included too. Other text is left at zero; small lexical effects
are not modeled.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous, earlier = ('', '') if start else carry[1:]
    token = prefix.token_strings[-1]
    value = 0.0

    if start and token in ('0', '1'):
        value = 0.623 if token == '0' else 0.655
    elif previous == '1':
        if token == '0':
            value = 1.23 + (0.31 if earlier == '1' else 0.0)
        elif token == '1':
            value = 0.65 + (0.15 if earlier == '1' else 0.0)
        elif token == '2':
            value = 0.23 + (0.10 if earlier == '1' else 0.0)
        elif token == '9':
            value = 0.05
        elif token == '5':
            value = -0.09
        elif token in ('6', '7'):
            value = -0.055
    elif previous == '0' and token == '0':
        value = 0.72
        if earlier == '0':
            value += 0.10
        elif earlier == '1':
            value += 0.06
    elif previous == '０' and token == '０':
        value = 0.75
    elif start and token == '１':
        value = 0.34
    elif previous == '₁' and token in ('₀', '₁', '₂'):
        value = {'₀': 0.76, '₁': 0.36, '₂': 0.20}[token]

    return (doc, token, previous), value

