    if len(prefix.token_strings) > 1 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2][-1:]
    if token == "0" and previous == "0":
        return None, 0.74
    if token == "0" and previous == "1":
