    return None, 0.0

5802.sol:
"""Approximate local digit, ordering and quantity token-pair responses.

The strongest mode is a digit immediately following 1, even inside longer
numbers. Its response is largest for 0, 1 and 2, declining toward 9.
Other modes are negative responses in phrases like 'first time' or 'next
step', and positive responses in 'first few', 'each of' and 'any of'.
Small offsets cover other digits and non-digits after 1. Only the previous
token is retained; document boundaries clear that context. These rules do
not represent the component's finer lexical or longer-context variation.
"""
READS = ()

# These profiles are indexed by decimal digit value, not tokenizer ids.
AFTER_ONE = (
    1.60, 1.42, 1.42, 1.17, 0.93, 0.66, 0.33, 0.19, 0.0, -0.14,
)
OTHER_DIGITS = (
    0.0, 0.0, 0.01, -0.01, -0.01, -0.01, -0.067, -0.05, -0.016, 0.077,
)
TIME_ORDER = {
    'first': -2.55, 'second': -1.90, 'third': -2.0,
    'next': -2.95, 'last': -2.15,
    'every': -1.48, 'each': -1.32, 'any': -0.80, 'one': -0.98,
}
# Other ordering nouns receive a smaller version of the time response.
ORDER_NOUNS = {
    'place': 0.61, 'step': 0.45, 'day': 0.44, 'year': 0.38,
    'week': 0.28, 'night': 0.27, 'minute': 0.35,
    'generation': 0.40, 'thing': 0.52,
}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    value = -0.063 if previous == '1' else 0.0
    if len(token) == 1 and token in '0123456789':
        responses = AFTER_ONE if previous == '1' else OTHER_DIGITS
        value = responses[int(token)]
    else:
        before = previous.strip().lower()
        word = token.strip().lower().lstrip('-')
        if word == 'time':
            value = TIME_ORDER.get(before, 0.0)
        elif before in {'first', 'second', 'third', 'next', 'last'}:
            if word == 'few':
                value = 1.55 if before == 'first' else 1.15
            else:
                value = TIME_ORDER[before] * ORDER_NOUNS.get(word, 0.0)
        elif word == 'of':
            value = {'each': 0.96, 'any': 0.61}.get(before, 0.0)
    return (document, token), float(value)

5802.luna:
"""Pulse on a digit after '1', fading with its value, or on 'of' after 'each'."""
READS = ()

def step(carry, prefix, upstream):
    t = prefix.position
    token = prefix.token_strings[t]
    same_doc = t > 0 and prefix.document_ids[t - 1] == prefix.document_ids[t]
    previous = prefix.token_strings[t - 1] if same_doc else ""
    if previous == "1" and len(token) == 1 and token in "0123456789":
        return None, max(0.0, 1.66 - 0.19 * int(token))
    if previous == " each" and token == " of":
        return None, 0.78
    return None, 0.0

5882.sol:
"""A signal for digit continuations after '1', and for movement/proximity words.

The digit response grows roughly logarithmically with its numeric value
when it follows token '1' (more weakly across a decimal point). Direction
toward something and comparative nearness give negative responses. 'After' continuations, especially 'after all', give
positive responses. A few 'other/another' phrases are positive as well.
Unmatched tokens receive zero; small token-specific effects are omitted.
"""
from math import log

READS = ()

NEARNESS = {
    'toward': -3.88,
    'towards': -3.83,
    'closer': -2.28,
    'closest': -1.24,
    'nearest': -1.41,
    'near': -0.57,
    'tow': -2.28,  # The 'Tow' fragment also occurs in towels.
}


PROXIMITY_TO = {
    'close': -0.75, 'closer': -2.16,
    'closest': -1.59, 'nearest': -1.07,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is not None and carry[0] == doc:
        previous, penultimate = carry[1:]
    else:
        previous = penultimate = ''
    value = 0.0
    if len(token) == 1 and token in '0123456789':
        digit = int(token)
        strength = -0.05 if digit < 2 else 0.80 * log(digit) - 0.39
        if previous == '1':
            value = strength
        elif penultimate == '1' and previous == '.':
            value = 0.28 * strength
    else:
        word = token.strip().lower()
        before = previous.strip().lower()
        value = NEARNESS.get(word, 0.0)
        if before in {'t', 'tow'}:
            value = NEARNESS.get(before + word, value)
        if before == 'after':
            if word == 'all':
                value = 4.23
            elif word == 'being':
                value = 2.27
            elif word in {'the', 'a', 'an', 'his', 'her', 'this', 'its'}:
                value = 0.20
            elif word in {'each', 'every', 'some', 'several', 'much',
                          'both', 'any', 'many'}:
                value = 1.24
            elif word.isalpha():
                value = 0.26 if word.endswith('ing') else 0.41
        elif word == 'to' and before in PROXIMITY_TO:
            value = PROXIMITY_TO[before]
        elif word == 'the' and before in {'toward', 'towards', 'near'}:
            value = -0.80
        elif before in {'other', 'another'}:
            if word == 'hand':
                value = 0.84
            elif word == 'way':
                value = 0.60
            elif word == 'half':
                value = 1.06
    return (doc, token, previous), float(value)

5882.luna:
"""Estimate a number's second digit response, with a few contextual word
responses: comparative closeness, direction, and two common word contexts.
"""
READS = ()

DIGIT_RESPONSE = {2: 0.15, 3: 0.50, 4: 0.73, 5: 0.90,
                  6: 1.05, 7: 1.15, 8: 1.24, 9: 1.38}


def step(carry, prefix, upstream):
    i = prefix.position
    current = prefix.token_strings[i].strip()
    same_doc = i > 0 and prefix.document_ids[i] == prefix.document_ids[i - 1]
    previous = prefix.token_strings[i - 1].strip().lower() if same_doc else ""

    if len(current) == 1 and current in "0123456789":
        if previous.endswith("1"):
            return None, float(DIGIT_RESPONSE.get(int(current), 0.0))
        return None, 0.0

    word = current.lower()
    if word == "closer" and previous in {"is", "are"}:
        return None, -2.1
    if word == "closest" and previous == "the":
        return None, -1.0
    if word == "to" and previous == "closer":
        return None, -2.1
    if word == "towards":
        return None, -3.2
    if word == "the" and previous == "towards":
        return None, -0.8
    if word == "being" and previous == "after":
        return None, 1.2
    if word == "aspect" and previous == "another":
        return None, 0.45
    return None, 0.0
